function dates(){const single=state.mode==='day';return `<div class="filter-panel"><div class="segmented"><button data-mode="day" class="${single?'active':''}">Ден</button><button data-mode="period" class="${state.mode==='period'?'active':''}">Период</button><button data-mode="all" class="${state.mode==='all'?'active':''}">Всички</button></div>${state.mode!=='all'?`<div class="date-inputs"><label><span>${single?'Дата':'От дата'}</span><input id="from-date" type="date" value="${iso(state.from)}"></label>${!single?`<label><span>До дата</span><input id="to-date" type="date" value="${iso(state.to)}"></label>`:''}<button id="apply-date" class="btn blue">Покажи</button></div>`:''}</div>`}
function period(){return state.mode==='all'?'':`&from=${encodeURIComponent(state.from)}&to=${encodeURIComponent(state.mode==='day'?state.from:state.to)}`}
function bindDates(){document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.mode=b.dataset.mode;if(state.tab==='archive')archiveState.offset=0;if(state.tab==='builders')builderHistoryState.offset=0;render()});const apply=$('#apply-date');if(apply)apply.onclick=()=>{const f=$('#from-date').value;if(!f)return;state.from=bg(f);if(state.mode==='period'){const t=$('#to-date').value;if(!t)return;state.to=bg(t);if(iso(state.to)<iso(state.from)){showError('Крайната дата трябва да е след началната.');return}}if(state.tab==='archive')archiveState.offset=0;if(state.tab==='builders')builderHistoryState.offset=0;render()}}
async function api(kind,extra=''){const key=kind+extra;const r=await fetch('/api/data?kind='+kind+extra,{headers:{Authorization:'Bearer '+state.token},cache:'no-store'});const d=await r.json().catch(()=>({error:'Невалиден отговор'}));if(r.status===401){state.token='';sessionStorage.removeItem('ds-token');if(!$('#login').open)$('#login').showModal()}if(!r.ok)throw Error(d.error||'Грешка '+r.status);return d}
function showError(msg){$('#content').innerHTML=`<div class="error"><b>Не успяхме да заредим данните</b><p>${esc(msg)}</p><button class="btn blue" id="retry">Опитай отново</button></div>`;$('#retry').onclick=render}
function badge(s){const names={win:'Печели',loss:'Губи',void:'Върнат',pending:'Предстоящ'};return `<span class="status ${s}">${names[s]||'Предстоящ'}</span>`}
function item(p){const teams=teamNames(p.match),logos=teams.length===2?'<span class="ds22-inline-crests">'+teams.map(t=>crestHTML(t,p.league)).join('')+'</span>':'';return `<article class="match-card"><div class="match-top"><span>${esc(p.time||p.date||'')} ${p.league?'· '+dsLeagueHTML(p.league):''}</span>${badge(p.status)}</div><div class="match-title ds22-with-crests">${logos}${esc(p.match)}</div><div class="match-pick"><span>${esc(shortPick(p.selection,p.match))}</span><b>${p.odds?fmt(p.odds):'—'}</b></div>${p.level?`<div class="match-meta">Увереност ${esc(confidence(p))}</div>`:''}</article>`}
function summaryCard(label,value,ic,cl=''){return `<div class="metric ${cl}"><div class="metric-top"><span class="metric-icon">${ic}</span><span>${label}</span></div><strong>${value}</strong></div>`}
function statCards(x){return `<div class="metrics">${summaryCard('Печалба',signed(x.profit)+' u','↗',color(x.profit))}${summaryCard('Yield',signed(x.yield)+'%','▥',color(x.yield))}${summaryCard('Успеваемост',fmt(x.wr)+'%','◎')}${summaryCard('Залози',fmt(x.count),'▱')}</div>`}
function section(title,action=''){return `<div class="section-head"><h2>${title}</h2>${action}</div>`}
function empty(msg){return `<div class="empty"><div class="empty-icon">◇</div><b>Няма намерени записи</b><p>${esc(msg)}</p></div>`}
