function groupedMatches(rows){const groups=new Map();for(const p of rows){const k=[p.section||'default',p.date,p.match].join('|');if(!groups.has(k))groups.set(k,{key:k,date:p.date,time:p.time,league:p.league,match:p.match,items:[]});const g=groups.get(k);if(!g.time&&p.time)g.time=p.time;if(!g.league&&p.league)g.league=p.league;g.items.push(p)}return [...groups.values()].sort((a,b)=>(iso(b.date)+b.time).localeCompare(iso(a.date)+a.time))}
