function crestHTML(team,league){const flag=dsNationalFlag(team,league);const country=(dsCountry(league)||[])[2]||'';return '<span class="ds11-crest'+(flag?' ds15-national':'')+'" data-team="'+esc(team)+'" data-national="'+(flag?'1':'0')+'" data-country="'+esc(country)+'">'+(flag?dsFlagHTML(flag,'ds-national-flag'):'<span class="ds-crest-placeholder" aria-label="Емблемата не е налична">⚽</span>')+'</span>'}
const crestLookupCache=new Map();
const dsCrestBlocked=new Set(['celta fortuna','tarancón','tarancon']); // Unverified remote result; never show an invented CF shield.
function crestLookup(team,country){if(dsCrestBlocked.has(String(team).trim().toLowerCase()))return Promise.resolve(null);const key=(team+'|'+(country||'')).trim().toLowerCase();if(crestLookupCache.has(key))return crestLookupCache.get(key);const task=(async()=>{try{const cached=localStorage.getItem('ds-crest-v24:'+key);if(cached)return cached}catch(e){}try{const r=await fetch('/api/crests?team='+encodeURIComponent(team)+'&country='+encodeURIComponent(country||''));if(!r.ok)return null;const d=await r.json();if(d.url){try{localStorage.setItem('ds-crest-v24:'+key,d.url)}catch(e){}return d.url}}catch(e){}return null})();crestLookupCache.set(key,task);return task}
