function hydrateCrests(){
 const els=[...document.querySelectorAll('.ds11-crest[data-team]:not([data-national="1"])')];if(!els.length)return;
 if(!crestManifestPromise)crestManifestPromise=fetch('/crests/manifest.json?v=224').then(r=>r.ok?r.json():{}).catch(()=>({}));
 crestManifestPromise.then(map=>{const names=[...new Set(els.map(el=>el.dataset.team))];for(const name of names){
  const targets=els.filter(el=>el.dataset.team===name);const key=name.toLowerCase();if(dsCrestBlocked.has(key))continue;
  Promise.resolve(map[key]||crestLookup(name,targets[0]?.dataset.country)).then(src=>{if(!src)return;for(const el of targets){if(!el.isConnected)return;const img=document.createElement('img');img.src=src;img.alt='Емблема '+name;img.loading='lazy';img.referrerPolicy='no-referrer';img.onerror=()=>{img.onerror=null;img.replaceWith(document.createTextNode('⚽'));el.classList.remove('has-crest')};el.replaceChildren(img);el.classList.add('has-crest')}})
 }})
}
