function dsCountryKey(name){const t=String(name||'').toLocaleLowerCase('en').replace(/[_–—]/g,' ').trim();if(!t)return null;for(const k of dsCountryKeys){if(t===k||t.startsWith(k+' ')||t.endsWith(' '+k)||t.includes(' '+k+' ')||t.includes('('+k+')'))return k}for(const k of dsCountryAliasKeys){if(t.includes(k)){const country=dsCountryAliases[k];if(dsCountryCodes[country])return country}}return null}
function dsCountry(name){const k=dsCountryKey(name);if(!k)return null;const code=dsCountryCodes[k];const country=dsCountryMap[k]||Object.entries(dsCountryMap).find(([name])=>dsCountryCodes[name]===code)?.[1];if(country)return [...country,code];let pretty=String(k).replace(/\b\w/g,ch=>ch.toUpperCase());try{if(code.length===2)pretty=new Intl.DisplayNames(['bg'],{type:'region'}).of(code.toUpperCase())||pretty}catch(e){}const flag=code.length===2?String.fromCodePoint(...[...code.toUpperCase()].map(c=>0x1F1E6+c.charCodeAt(0)-65)):'🌐';return [pretty,flag,code]}
function dsFlagHTML(c,extraClass=''){if(!c)return '🌐';if(!c[2])return c[1]||'🌐';return '<img class="ds-flag-icon '+extraClass+'" src="/flags/'+encodeURIComponent(c[2])+'.svg" alt="'+esc(c[1]||c[0])+'" data-fallback="'+esc(c[1]||'🌐')+'" loading="lazy">'}
function dsLeagueLabel(league){const c=dsCountry(league);return (c?c[1]+' '+c[0]+' · ':'🌐 Държава неуточнена · ')+String(league||'Неизвестна лига')}
function dsLeagueHTML(league){const c=dsCountry(league);return (c?dsFlagHTML(c)+' '+esc(c[0])+' · ':'🌐 Държава неуточнена · ')+esc(league||'Неизвестна лига')}
function dsNationalFlag(team,league){const normalized=String(team||'').toLocaleLowerCase('en').replace(/[_–—]/g,' ').trim().replace(/^(u(?:1[5-9]|2[0-3])|women)\s+/,'').replace(/\s+(?:u(?:1[5-9]|2[0-3])|women|w|ladies|female)$/,'').trim();if(!Object.prototype.hasOwnProperty.call(dsCountryCodes,normalized))return null;/* AS Monaco plays as a French club; country-name overlap must not turn its crest into a flag. */if(normalized==='monaco'&&!/international|national|world cup|qualification|qualifiers|friendly|nations league|световн|национал/i.test(String(league||'')))return null;return dsCountry(normalized)}
function dsBuilderOdds(items){const nums=items.map(x=>Number(String(x.odds??'').replace(',','.')));return nums.length&&nums.every(n=>Number.isFinite(n)&&n>1)?nums.reduce((v,n)=>v*n,1):null}
function dsOddsLabel(n){return n===null?'—':n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:5,useGrouping:false})}
function dsBuilderStatus(items,day){if(!items.length)return 'pending';const statuses=items.map(x=>x.status);if(statuses.includes('loss'))return 'loss';if(statuses.every(x=>x==='win'||x==='void'))return statuses.every(x=>x==='void')?'void':'win';return 'pending'}
function dsBuilderBadge(status){return '<span class="ds15-builder-status '+status+'">'+({win:'✓ Спечелен',loss:'✕ Загубен',void:'↩ Върнат',pending:'◷ Неприключил'}[status]||'◷ Неприключил')+'</span>'}
function dsBuilderCard(p){const items=p.items||[];const odds=dsBuilderOdds(items);const result=dsBuilderStatus(items,p.date);const effectiveOdds=items.every(x=>Number(x.odds)>1)?items.reduce((n,x)=>n*(x.status==='void'?1:Number(x.odds)),1):null;const modelPL=result==='loss'?-1:result==='void'?0:result==='win'&&effectiveOdds!==null?effectiveOdds-1:null;const leagues=new Map();for(const x of items){const key=String(x.league||'Неизвестна лига');if(!leagues.has(key))leagues.set(key,[]);leagues.get(key).push(x)}const groups=[...leagues].map(([league,legs])=>'<section class="ds15-league"><div class="ds15-league-title">'+dsLeagueHTML(league)+'</div>'+legs.map(x=>{const teams=teamNames(x.match);return '<div class="ds15-leg"><div class="ds20-leg-head">'+(teams.length===2?'<span class="ds20-leg-crests">'+teams.map(t=>crestHTML(t,league)).join('')+'</span>':'')+'<div class="ds15-leg-match">'+esc(x.match||'')+'</div><span class="ds20-confidence" title="Увереност '+esc(confidence(x))+'">'+esc(confidence(x))+'</span></div><div class="ds15-leg-bottom"><span>'+esc(shortPick(x.selection,x.match))+' '+dsBuilderBadge(x.status)+'</span><b>'+dsOddsLabel(Number(x.odds)||null)+'</b></div></div>'}).join('')+'</section>').join('');return '<article class="ds15-builder ds20-builder"><div class="ds15-builder-head"><span class="ds14-luxe-symbol">✧</span><div><strong>Best of the Day · билдър</strong><small>'+esc(p.date)+' · '+items.length+' селекции</small></div>'+dsBuilderBadge(dsBuilderStatus(items,p.date))+'</div><div class="ds15-builder-leagues">'+groups+'</div><div class="ds15-builder-total"><span>Общ коефициент<small>Произведение на всички коефициенти</small></span><strong>'+dsOddsLabel(odds)+'</strong></div><div class="ds20-builder-foot">Предложение, не потвърден залог'+(modelPL===null?'':' · Моделен P/L при 1u: '+signed(modelPL)+' u')+'</div></article>'}
function ds27Ratio(value){const m=String(value??'').match(/(\d{1,2})\s*\/\s*(10|\d{1,2})/);return m?m[1]+'/'+m[2]:null}
function groupedCard(g){
 const open=state.expandedMatch===g.key,teams=teamNames(g.match);
 const picks=g.items.map(p=>{
 const home=ds27Ratio(p.homeLast10)||'—',away=ds27Ratio(p.awayLast10)||'—';
 return '<section class="ds26-selection">'+(p.section==='beta'?'<div class="ds-beta-pick-label">β '+esc(p.strategyLabel||'Beta Strategy')+'</div>':p.strategies?.length?'<div class="ds-beta-pick-label">A–F · '+esc(p.strategies.join(', '))+'</div>':'')+'<div class="ds26-pick-heading"><strong>'+esc(shortPick(p.selection,p.match))+'</strong>'+badge(p.status)+'</div><div class="ds26-pick-metrics"><div><span>Коефициент</span><strong>'+dsOddsLabel(Number(p.odds)>1?Number(p.odds):null)+'</strong></div><div><span>Увереност</span><strong>'+esc(confidence(p))+'</strong></div></div><div class="ds26-last10"><div class="ds26-detail-field"><span>'+esc(teams[0]||'Домакин')+' · последни 10</span><strong>'+esc(home)+'</strong></div><div class="ds26-detail-field"><span>'+esc(teams[1]||'Гост')+' · последни 10</span><strong>'+esc(away)+'</strong></div></div></section>';
 }).join('');
 const visible=g.items.length>1&&!open?picks.slice(0,picks.indexOf('</section>')+10):picks;
 return '<article class="fixture ds11-fixture ds13-match-card ds26-match-card ds-smooth-fixture"><div class="ds-smooth-fixture-head"><div class="ds11-fixture-top">'+dsLeagueHTML(g.league)+' · '+esc(g.date)+' · '+esc(g.time||'')+'</div><div class="ds11-teams">'+(teams.length===2?'<span class="ds11-team">'+crestHTML(teams[0],g.league)+'<b>'+esc(teams[0])+'</b></span><span class="ds11-vs">—</span><span class="ds11-team">'+crestHTML(teams[1],g.league)+'<b>'+esc(teams[1])+'</b></span>':'<b>'+esc(g.match)+'</b>')+'</div><div class="ds26-picks">'+visible+'</div></div>'+(g.items.length>1?'<button type="button" class="ds-smooth-expand" data-fixture="'+esc(g.key)+'" aria-expanded="'+open+'"><span>'+(!open?'Покажи всички '+g.items.length+' селекции':'Покажи по-малко')+'</span><span class="ds-smooth-expand-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg></span></button>':'')+'<button type="button" class="dsms-entry" data-match-stats="'+esc(g.match)+'" data-stats-date="'+esc(g.date)+'">▥ Статистика на мача</button></article>';
}
