 const unique=new Map();
 for(const p of [...ds27BuilderPicks(buildersData),...ds27StrategyPicks(strategyData)]){
 const key=[p.date,p.match,p.selection].join('|'),old=unique.get(key);
 unique.set(key,old?{...old,...p,level:p.level||old.level,homeLast10:p.homeLast10||old.homeLast10,awayLast10:p.awayLast10||old.awayLast10}:p);
 }
 return [...unique.values()];
