function oracleBuilderCard(p){const type=String(p.BUILDER_TYPE||'');const status=String(p.RESULT_STATUS||'pending').toLowerCase();const day=String(p.MATCH_DATE||'');const odds=Number(p.ODDS);const legs=Number(p.LEGS)||0;const pl=p.PROFIT_UNITS===null||p.PROFIT_UNITS===undefined?null:Number(p.PROFIT_UNITS);return '<article class="match-card ds21-builder-history"><div class="match-top"><span>'+esc(day)+' · '+legs+' селекции · Oracle</span>'+dsBuilderBadge(status)+'</div><div class="match-title">'+esc(type==='BEST_PROPOSAL'?'✧ Best of the Day · архив':'Мой записан билдър · архив')+'</div><div class="match-pick"><span>Общ коефициент</span><b>'+dsOddsLabel(odds>1?odds:null)+'</b></div>'+(pl!==null?'<div class="match-meta '+color(pl)+'">P/L '+signed(pl)+' u</div>':'')+'</article>'}
async function oracleBuilderHistory(){const url='/api/history?kind=builders&type='+(state.builderTab==='mine'?'RECORDED':'BEST_PROPOSAL')+'&offset='+builderHistoryState.offset+'&limit='+builderHistoryState.limit+(state.mode==='all'?'':'&from='+encodeURIComponent(iso(state.from))+'&to='+encodeURIComponent(iso(state.mode==='day'?state.from:state.to)));const r=await fetch(url,{headers:{Authorization:'Bearer '+state.token},cache:'no-store'});const d=await r.json().catch(()=>({error:'Невалиден отговор от Oracle'}));if(!r.ok)throw Error(d.error||'Oracle HTTP '+r.status);return d}
