function chart(points){
 const ordered=[...(points||[])].filter(p=>p&&p.date&&Number.isFinite(Number(p.pl))).sort((a,b)=>{const date=x=>/^\d{2}\.\d{2}\.\d{4}$/.test(x)?x.split('.').reverse().join('-'):x;return date(a.date).localeCompare(date(b.date))});
 if(!ordered.length)return '<div class="ds12-chart-empty"><b>Все още няма приключили залози</b><span>Графиката ще се появи след първия отчетен резултат.</span></div>';
 let total=0;const values=[{date:'Начало',value:0},...ordered.map(p=>({date:p.date,value:total+=Number(p.pl)}))];
 const w=720,h=254,l=48,r=18,t=18,b=40;const low=Math.min(0,...values.map(v=>v.value)),high=Math.max(0,...values.map(v=>v.value));const pad=Math.max((high-low)*.14,1);const min=low-pad,max=high+pad;const x=i=>l+(w-l-r)*(i/(values.length-1||1)),y=v=>t+(h-t-b)*(max-v)/(max-min||1);
 const coords=values.map((v,i)=>[x(i),y(v.value)]);const path=coords.map(([px,py],i)=>(i?'L':'M')+px.toFixed(1)+' '+py.toFixed(1)).join(' ');const area=path+' L'+x(values.length-1).toFixed(1)+' '+(h-b)+' L'+l+' '+(h-b)+' Z';const zero=y(0);const ticks=Array.from({length:5},(_,i)=>min+(max-min)*i/4);
 const grid=ticks.map(v=>'<line x1="'+l+'" y1="'+y(v).toFixed(1)+'" x2="'+(w-r)+'" y2="'+y(v).toFixed(1)+'" stroke="#2b4056" stroke-dasharray="4 6" stroke-width="1"/><text x="'+(l-9)+'" y="'+(y(v)+4).toFixed(1)+'" text-anchor="end" fill="#8fa6bd" font-size="12">'+esc(fmt(v))+'</text>').join('');
 const last=coords[coords.length-1],start=ordered[0].date,end=ordered[ordered.length-1].date;
 return '<div class="ds12-chart"><div class="ds12-chart-head"><div><small>НАТРУПАНА ПЕЧАЛБА</small><strong class="'+color(total)+'">'+signed(total)+' u</strong></div><span class="ds12-chart-count">'+ordered.length+' отчетни дни</span></div><svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Натрупана печалба от '+esc(start)+' до '+esc(end)+'"><defs><linearGradient id="ds12Fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#25e9ac" stop-opacity=".32"/><stop offset="100%" stop-color="#25e9ac" stop-opacity="0"/></linearGradient><linearGradient id="ds12Stroke" x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stop-color="#05bdb8"/><stop offset="100%" stop-color="#3df6a2"/></linearGradient></defs>'+grid+'<line x1="'+l+'" y1="'+zero.toFixed(1)+'" x2="'+(w-r)+'" y2="'+zero.toFixed(1)+'" stroke="#7995ab" stroke-opacity=".7" stroke-width="1.3"/><path d="'+area+'" fill="url(#ds12Fill)"/><path d="'+path+'" fill="none" stroke="url(#ds12Stroke)" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="'+last[0].toFixed(1)+'" cy="'+last[1].toFixed(1)+'" r="6" fill="#31efaa" stroke="#0d2431" stroke-width="3"/><text x="'+l+'" y="'+(h-10)+'" fill="#a4bbd1" font-size="13">'+esc(start)+'</text><text x="'+(w-r)+'" y="'+(h-10)+'" text-anchor="end" fill="#a4bbd1" font-size="13">'+esc(end)+'</text></svg><div class="ds12-chart-foot"><span>0 u = начално ниво</span><span>Печалба в единици (u)</span></div></div>';
}
